set search_path=public,extensions,auth;set timezone='UTC';
select jsonb_object_agg(k,v)from(select 'public.payments' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['id','parsed_event_id','payment_intent_id','collection_id','contributor_user_id','contributor_public_id','receiver_user_id','receiver_momo_number_hash','amount_rwf','currency','transaction_id','source','status','anonymity_choice','posted_at','created_at','provider_network','member_record_id']))j from public.payments t)s union all select 'collect_hybrid.momo_journal_entries' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['id','payment_id','parsed_event_id','collection_id','member_record_id','entry_type','amount_rwf','external_reference','reverses_entry_id','created_by','posted_at','created_at']))j from collect_hybrid.momo_journal_entries t)s union all select 'collect_hybrid.momo_journal_lines' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['id','journal_entry_id','account_code','direction','amount_rwf','created_at']))j from collect_hybrid.momo_journal_lines t)s union all select 'collect_hybrid.momo_balance_snapshots' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['id','journal_entry_id','payment_id','collection_id','member_record_id','event_type','delta_rwf','member_balance_after_rwf','group_balance_after_rwf','captured_at']))j from collect_hybrid.momo_balance_snapshots t)s union all select 'collect_hybrid.sms_notification_outbox' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['id','payment_id','snapshot_id','collection_id','member_record_id','destination_e164','destination_sha256','destination_revision','policy_revision','consent_revision','template_key','template_version','amount_rwf','member_balance_rwf','group_balance_rwf','reference','message_body','body_sha256','state','suppression_reason','fence_version','claim_token','claimed_by','claim_expires_at','attempt_count','created_at','updated_at','observed_sent_at']))j from collect_hybrid.sms_notification_outbox t)s union all select 'collect_receipt_operations.runs' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['id','request_id','principal_id','fence_version','policy_revision','mode','collection_ids','device_id','started_at','expires_at','scan_performed','completed_at']))j from collect_receipt_operations.runs t)s union all select 'collect_receipt_operations.requests' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['request_id','principal_id','action','request_sha256','input','issued_at','recorded_at','result']))j from collect_receipt_operations.requests t)s union all select 'collect_receipt_operations.handled_events' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['event_id','run_id','principal_id','source_version','code','receipt_id','handled_at']))j from collect_receipt_operations.handled_events t)s union all select 'collect_receipt_operations.run_events' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['run_id','event_id','source_version','code','business_handled','receipt_id','recorded_at']))j from collect_receipt_operations.run_events t)s union all select 'collect_receipt_operations.run_batch_events' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['run_id','event_id','assigned_at']))j from collect_receipt_operations.run_batch_events t)s union all select 'collect_receipt_operations.backlog_results' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['run_id','snapshot_id','code','business_handled','receipt_id','recorded_at']))j from collect_receipt_operations.backlog_results t)s union all select 'collect_receipt_operations.reservations' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['id','run_id','fence_version','collection_id','device_id','actions','sms_segments','recorded_at']))j from collect_receipt_operations.reservations t)s union all select 'collect_receipt_operations.event_deferrals' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['event_id','next_check_at','code']))j from collect_receipt_operations.event_deferrals t)s union all select 'collect_ops.receipt_backlog_budget_deferrals' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['request_id','run_id','snapshot_id','recorded_at']))j from collect_ops.receipt_backlog_budget_deferrals t)s)s;